using Mutagen.Bethesda.Plugins.Binary.Headers;
using Mutagen.Bethesda.Plugins.Meta;
using Mutagen.Bethesda.Starfield;
using Shouldly;
using Xunit;
using static Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield.StarfieldTestRecords;

namespace Mutagen.Bethesda.UnitTests.Plugins.Records.Starfield;

// BIOM GNAM (a procedural object) was a pack-in link and 80 raw bytes. The bytes follow xEdit's layout now:
// the floats xEdit types (Unknown2, Unknown4, ObjectDensity) are read as floats; the slots xEdit leaves unknown
// stay raw (Unknown1, Unknown3, Unknown5, Unknown6). The test reads a record from Starfield.esm with both
// readers and writes it back byte for byte.
public class BiomeObjectDensityTests
{
    // FrozenNoLife06 (0FC619:Starfield.esm): masks Talus and FlatInner, 54 objects. Every subrecord except FULL, which is
    // a localized string ID in Starfield.esm (the test reader is not localized).
    private const string Frozen = "";

    [Fact]
    public void ObjectDensity_Decoded()
    {
        var bytes = Record("BIOM", Hex(Frozen));
        foreach (var biom in ReadBoth<IBiomeGetter>(bytes,
                     f => Biome.CreateFromBinary(f),
                     (s, p) => BiomeBinaryOverlay.BiomeFactory(s, p)))
        {
            biom.EditorID.ShouldBe("FrozenNoLife06");
            biom.ProceduralObjectGeneration.Count.ShouldBe(2);

            var talus = biom.ProceduralObjectGeneration[0];
            talus.ProceduralObjectGenerationMaskName.ShouldBe("Talus");
            var first = talus.Objects[0];
            first.PackIn.FormKey.ID.ShouldBe(0x298973u);
            first.Unknown1.ToArray().ShouldBe(new byte[16]);
            first.Unknown2.ShouldBe(1f);
            first.Unknown3.ToArray().ShouldBe(new byte[28]);
            first.Unknown4.ShouldBe(1f);
            first.Unknown5.ToArray().ShouldBe(new byte[4]);
            first.ObjectDensity.ShouldBe(0.2f);
            first.Unknown6.ToArray().ShouldBe(Hex("0000803F00000000050000000000000000000000"));

            var flatInner = biom.ProceduralObjectGeneration[1];
            flatInner.ProceduralObjectGenerationMaskName.ShouldBe("FlatInner");
            flatInner.Objects[0].ObjectDensity.ShouldBe(0.022891378f);

            var all = biom.ProceduralObjectGeneration.SelectMany(x => x.Objects).ToList();
            all.Count.ShouldBe(54);
            all.Count(o => o.Unknown6.Span.SequenceEqual(Hex("0000803F00000000FFFF7F7F0000000005000000"))).ShouldBe(4);

            var written = GameConstants.Starfield.MajorRecord(Write(w => biom.WriteToBinary(w)));
            written.Content.ToArray().ShouldBe(Hex(Frozen));
        }
    }
}
